        vm.assume(_tos.length > 0 && _tos.length <= 50);

        // Track the selector that will be used by encoding the call
        bytes4 expectedSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // We need to check what selector is used. Since we can't read internal state,
        // we'll check the behavior: if the contract uses safeTransferFrom, it will fail
        // when calling a simple contract that only has transferFrom

        // Deploy a minimal mock that only accepts transferFrom
        MockTransferFrom mock = new MockTransferFrom();

        // Call transfer with the mock's address
        (bool success, ) = address(c).call(
            abi.encodeWithSignature(
                "transfer(address,address,address[],uint256)",
