pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        // Record balances before transfer
        uint[] memory beforeBalances = new uint[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success);
            beforeBalances[i] = abi.decode(data, (uint));
        }

        // Perform transfer
        c.transfer(from, caddress, _tos, v);

        // Record balances after transfer
        uint totalDelta = 0;
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success);
            uint afterBalance = abi.decode(data, (uint));
            totalDelta += afterBalance - beforeBalances[i];
        }

        // The total change should equal v * _tos.length
        assertTrue(totalDelta == v * _tos.length, "Sum of balance changes should equal v * _tos.length");
    }
}

