            vm.assume(_tos[i] != address(0));
        }
        // Record balances of all recipients before the transfer
        uint256[] memory balancesBefore = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success, "balanceOf call failed before");
            balancesBefore[i] = abi.decode(data, (uint256));
        }

        // Call the transfer function
        c.transfer(from, caddress, _tos, v);

        // Check that each recipient's balance increased by exactly v
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success, "balanceOf call failed after");
            uint256 balanceAfter = abi.decode(data, (uint256));
            assertTrue(balanceAfter == balancesBefore[i] + v, "Balance did not increase by v");
        }
    }
}

