    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // We need to simulate that caddress is an ERC20 contract with transferFrom and transfer
        // but we can't deploy it in fuzz. Instead, we check that the call reverts if the selector is wrong.
        // Actually, we can deploy a mock ERC20 that only has transferFrom.
        // For the fuzz test, we'll just check that the function doesn't revert when the selector is correct
        // and the mock is properly set up. Since we can't deploy in fuzz, we'll use a simpler property:
