        // the correct selector is used.
        // Actually, we can check that the function returns true (doesn't revert) for any valid inputs.
        // Since we don't have a mock, we'll just check that the function doesn't revert when called with
        // a contract that has the expected interface. But we can't guarantee that in fuzz.
        // Simpler: check that the function succeeds (returns true) for any inputs (assuming caddress is a valid contract).
        // Since we can't control caddress, we use try/catch to check it doesn't revert.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        assertTrue(ok);
    }
