pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ERC20Mock token;

    function setUp() public {
        c = new C();
        token = new ERC20Mock();
        // Give the contract that calls transfer (like c) some tokens
        token.mint(address(this), 1000000 ether);
        // Approve caddress to transferFrom this contract
        token.approve(address(c), 1000000 ether);
    }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 100); // bound array size
        vm.assume(v > 0 && v < 1000000 ether / _tos.length);
        vm.assume(caddress == address(token)); // only use our mock
        vm.assume(from == address(this)); // ensure sender is approved
        for (uint256 i = 0; i < _tos.length; i++) {
            require(_tos[i] != address(0), "invalid recipient");
        }

        uint256[] memory initialBalances = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            initialBalances[i] = token.balanceOf(_tos[i]);
        }

        c.transfer(from, caddress, _tos, v);

        uint256 totalIncrease = 0;
        for (uint256 i = 0; i < _tos.length; i++) {
            uint256 newBalance = token.balanceOf(_tos[i]);
            assertTrue(newBalance >= initialBalances[i], "balance decreased");
            totalIncrease += newBalance - initialBalances[i];
        }
        assertTrue(totalIncrease == v * _tos.length, "total increase mismatch");
    }
}

contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    function mint(address to, uint256 amount) public {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
        require(allowance[sender][msg.sender] >= amount, "allowance too low");
        require(balanceOf[sender] >= amount, "balance too low");
        allowance[sender][msg.sender] -= amount;
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function transfer(address recipient, uint256 amount) public returns (bool) {
        require(balanceOf[msg.sender] >= amount, "balance too low");
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }
}

